    {
      "card_ids": ["C10"],
      "claim": "Levodopa absolute oral bioavailability was 80.4% in healthy volunteers after fasting, a direct human F measurement well above the 20% threshold; the high transfer score supports high F for the query's amino-acid/peptide-like polar structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Baclofen absolute oral bioavailability was 85.8% in healthy volunteers; as a small zwitterionic amino-acid analogue, it supports efficient oral absorption for the query's amino-acid-bearing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Desvenlafaxine absolute oral bioavailability is approximately 80% in humans; the high transfer score supports high F for a phenolic small molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Maraviroc oral bioavailability was 33% in healthy subjects, still above the 20% threshold; this demonstrates that even moderate F values support a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Garenoxacin absolute oral bioavailability was 92% after a 600 mg oral dose; supports high F for a carboxylic-acid-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Seletracetam oral bioavailability was >90% in humans; the high transfer score supports high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental evidence, with high assay-transfer scores, reports absolute oral bioavailability values above 20% (roughly 33% to >90%) in humans. The query's amino-acid/peptide-like cephalosporin structure is consistent with transporter-mediated oral absorption; therefore predict high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query or a close cephalosporin analogue.",
    "All retrieved evidence molecules are non-beta-lactam drugs, so transfer relies on general small-molecule absorption properties rather than exact structural class.",
    "Potential acid lability, efflux, or instability of the cephalosporin core is not directly addressed by the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

